static inline uint32_t crc32(uint32_t crc, const void *buf, uint32_t size,
			     const uint32_t *tab)
{
	const uint8_t *p = (const uint8_t *)buf;

	while (size--)
		crc = tab[(crc ^ *p++) & 0xFF] ^ (crc >> 8);

	return (crc);
}

uint32_t ext4_crc32(uint32_t crc, const void *buf, uint32_t size)
{
	return crc32(crc, buf, size, crc32_tab);
}

uint32_t ext4_crc32c(uint32_t crc, const void *buf, uint32_t size)
{
	const uint8_t *p = (const uint8_t *)buf;
	const uint8_t *end = p + (size & ~UINT32_C(3));

	/*
	 * Slicing-by-4 for the reflected Castagnoli polynomial.  These tables are
	 * derived from crc32c_tab[0] by repeatedly applying its byte recurrence.
	 * Byte loads keep this correct and fast on unaligned big-endian MC68030
	 * buffers without an endian conversion or alignment branch.
	 */
	while (p != end) {
		crc = crc32c_tab[3][(crc ^ p[0]) & 0xff] ^
		      crc32c_tab[2][((crc >> 8) ^ p[1]) & 0xff] ^
		      crc32c_tab[1][((crc >> 16) ^ p[2]) & 0xff] ^
		      crc32c_tab[0][((crc >> 24) ^ p[3]) & 0xff];
		p += 4;
	}

	return crc32(crc, p, size & UINT32_C(3), crc32c_tab[0]);
}

